INSERT INTO `news` (`id`, `title`, `category`, `excerpt`, `image_path`, `published_at`, `created_at`, `updated_at`, `content`, `slug`, `gallery_images`) VALUES (1, 'Annulation du contrat d\'achat d\'or : Riverstone Karma SA salue une décision judiciaire historique', 'Gouvernance', 'Par jugement en date du 10 juin 2026, le Tribunal de commerce de Ouagadougou a statué en faveur de Riverstone Karma SA dans le différend qui l’opposait aux sociétés Franco-Nevada et Sandstorm Gold Ltd (aujourd’hui IRC).', 'news/FygENNJr36vgw9vcHOKKRXXjCM3R2t5pFsWppYO8.jpg', '2026-07-20 00:00:00', '2026-09-07 13:52:26', '2026-09-08 07:53:22', 'La juridiction a prononcé l’annulation du Gold Purchase Agreement (GPA), un contrat d’achat d’or conclu en 2014, et a condamné solidairement les deux sociétés à verser à Riverstone Karma SA la somme de 5 218 224 600 francs CFA (environ 9,3 millions de dollars américains) à titre de réparation.
INSERT INTO `news` (`id`, `title`, `category`, `excerpt`, `image_path`, `published_at`, `created_at`, `updated_at`, `content`, `slug`, `gallery_images`) VALUES (2, 'Forum Mines 2026 : Néré Mining réaffirme son engagement en faveur des pratiques durables dans l\'exploitation minière', 'HSE', 'La troisième édition du Forum Mines a officiellement ouvert ses portes le mardi 7 juillet 2026 à Ouagadougou. Organisée par la Chambre des mines du Burkina, cette rencontre s’est déroulée du 7 au 9 juillet autour du thème : « Santé, sécurité et environnement : libérer le plein potentiel minier », sous le patronage du président de l’Assemblée législative du peuple.', 'news/nqMGQxXF6WivCvIrGEXI5nCQ1iMBv2DDIZky3vpH.jpg', '2026-07-16 00:00:00', '2026-09-07 13:52:26', '2026-09-08 07:55:04', 'Parmi les entreprises présentes au Forum Mines 2026 figure Riverstone Karma SA, détenue par la société Néré Mining. Elle est venue réaffirmer son engagement en matière de santé, de sécurité et d’environnement (HSE). Pour elle, cette participation constitue une occasion privilégiée de partager les expériences du secteur et de renforcer les bonnes pratiques.
INSERT INTO `news` (`id`, `title`, `category`, `excerpt`, `image_path`, `published_at`, `created_at`, `updated_at`, `content`, `slug`, `gallery_images`) VALUES (3, 'Semaine des Activités Minières de l\'Afrique de l\'Ouest', 'Événement', 'Retour sur la 6e édition de la SAMAO, consacrée aux stratégies de développement liées aux minéraux critiques pour les pays africains.', 'news/ClY1vOlgljZlrcugFSlfM4T6EBT019H7QBRyioKu.png', '2024-11-29 00:00:00', '2026-09-07 13:52:26', '2026-09-08 07:54:05', 'MOT DU PARRAIN
