INSERT INTO `karma_departments` (`id`, `tag_fr`, `tag_en`, `title_fr`, `title_en`, `body_fr`, `body_en`, `sort_order`, `is_published`, `created_at`, `updated_at`) VALUES (1, 'Administration', 'Administration', 'Administration de la mine', 'Mine Administration', 'Planification stratégique, gestion des opérations, supervision financière et conformité réglementaire. L\'administration coordonne les départements et les services techniques, HSE et ressources humaines.', 'Strategic planning, operations management, financial oversight and regulatory compliance. Administration coordinates the technical, HSE and human resources departments.', 1, 1, '2026-09-07 13:52:25', '2026-09-07 13:52:25');
INSERT INTO `karma_departments` (`id`, `tag_fr`, `tag_en`, `title_fr`, `title_en`, `body_fr`, `body_en`, `sort_order`, `is_published`, `created_at`, `updated_at`) VALUES (2, 'Ressources humaines', 'Human resources', 'Ressources humaines', 'Human Resources', 'Les ressources humaines gèrent le personnel et contribuent à garantir un environnement de travail productif, sûr et épanouissant.', 'Human resources manages personnel and helps ensure a productive, safe and fulfilling working environment.', 2, 1, '2026-09-07 13:52:25', '2026-09-07 13:52:25');
INSERT INTO `karma_departments` (`id`, `tag_fr`, `tag_en`, `title_fr`, `title_en`, `body_fr`, `body_en`, `sort_order`, `is_published`, `created_at`, `updated_at`) VALUES (3, 'Sûreté', 'Security', 'Département Sécurité', 'Security Department', 'Le dispositif comprend une CCTV de 44 caméras, une cellule drone, une brigade canine, une permanence des superviseurs 24h/24 et un service de transport entre Ouahigouya, Karma et Ouagadougou.', 'The system includes CCTV with 44 cameras, a drone unit, a canine brigade, supervisors on duty 24/7 and transport between Ouahigouya, Karma and Ouagadougou.', 3, 1, '2026-09-07 13:52:25', '2026-09-07 13:52:25');
INSERT INTO `karma_departments` (`id`, `tag_fr`, `tag_en`, `title_fr`, `title_en`, `body_fr`, `body_en`, `sort_order`, `is_published`, `created_at`, `updated_at`) VALUES (4, 'Opérations', 'Operations', 'Département Mining', 'Mining Department', 'Le processus minier regroupe la planification, les études de faisabilité, l\'analyse économique et les étapes techniques nécessaires à une extraction efficiente et sécurisée.', 'The mining process includes planning, feasibility studies, economic analysis and the technical steps required for efficient and safe extraction.', 4, 1, '2026-09-07 13:52:25', '2026-09-07 13:52:25');
INSERT INTO `karma_departments` (`id`, `tag_fr`, `tag_en`, `title_fr`, `title_en`, `body_fr`, `body_en`, `sort_order`, `is_published`, `created_at`, `updated_at`) VALUES (5, 'HSE', 'HSE', 'Hygiène, Santé, Sécurité et Environnement', 'Health, Safety and Environment', 'Le département HSE vise zéro incident grâce à la formation continue, aux inspections régulières, au suivi environnemental, à la gestion de la santé et au système de management HSE.', 'The HSE department targets zero incidents through continuous training, regular inspections, environmental monitoring, health management and an HSE management system.', 5, 1, '2026-09-07 13:52:25', '2026-09-07 13:52:25');
INSERT INTO `karma_departments` (`id`, `tag_fr`, `tag_en`, `title_fr`, `title_en`, `body_fr`, `body_en`, `sort_order`, `is_published`, `created_at`, `updated_at`) VALUES (6, 'Traitement', 'Processing', 'Département Processing', 'Processing Department', 'Le Processing est organisé en quatre sections : opérations, maintenance des équipements fixes, métallurgie et infrastructures. Il veille au traitement du minerai et à l\'optimisation de la production d\'or.', 'Processing is organised into four sections: operations, fixed equipment maintenance, metallurgy and infrastructure. It manages ore treatment and gold production optimisation.', 6, 1, '2026-09-07 13:52:25', '2026-09-07 13:52:25');
INSERT INTO `karma_departments` (`id`, `tag_fr`, `tag_en`, `title_fr`, `title_en`, `body_fr`, `body_en`, `sort_order`, `is_published`, `created_at`, `updated_at`) VALUES (7, 'Approvisionnement', 'Supply', 'Chaîne d’approvisionnement (SCM)', 'Supply Chain Department', 'Le SCM comprend les Achats, la Logistique, les Contrats et le Magasin. Il est dirigé par une équipe entièrement locale et garantit les biens, services et stocks nécessaires à la production.', 'Supply Chain comprises Procurement, Logistics, Contracts and Stores. It is led by an entirely local team and provides the goods, services and stocks required for production.', 7, 1, '2026-09-07 13:52:25', '2026-09-07 13:52:25');
INSERT INTO `karma_departments` (`id`, `tag_fr`, `tag_en`, `title_fr`, `title_en`, `body_fr`, `body_en`, `sort_order`, `is_published`, `created_at`, `updated_at`) VALUES (8, 'Technologies', 'Technology', 'Département IT', 'IT Department', 'Le département IT accompagne les équipes et les opérations de Karma grâce aux outils et services numériques nécessaires au fonctionnement du site.', 'The IT department supports Karma teams and operations through the digital tools and services required to run the site.', 8, 1, '2026-09-07 13:52:25', '2026-09-07 13:52:25');
INSERT INTO `karma_departments` (`id`, `tag_fr`, `tag_en`, `title_fr`, `title_en`, `body_fr`, `body_en`, `sort_order`, `is_published`, `created_at`, `updated_at`) VALUES (9, 'Dialogue local', 'Local dialogue', 'Relations communautaires', 'Community Relations', 'Le département gère les impacts sociaux, entretient le dialogue avec les communautés et soutient les autorités locales, coutumières et religieuses dans une approche pragmatique.', 'The department manages social impacts, maintains dialogue with communities and supports local, traditional and religious authorities through a pragmatic approach.', 9, 1, '2026-09-07 13:52:25', '2026-09-07 13:52:25');
